parameters.jsCode:
const item = $input.first().json;
let rawContent = item.choices?.[0]?.message?.content || '';

// Strip markdown code fences if wrapped in ```json ... ```
let cleaned = rawContent.trim();
const fenceMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
if (fenceMatch) {
  cleaned = fenceMatch[1].trim();
}

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { raw: cleaned, parse_error: e.message };
}

return {
  json: {
    status: 'success',
    provider: 'vireonix',
    raw: rawContent,
    cleaned: cleaned,
    data: parsed
  }
};

